 4  /// @title EtherVault
 5  /// @notice Users deposit ETH and withdraw it later. The owner can pause withdrawals.
 6  contract EtherVault {
 7      mapping(address => uint256) public balances;
 8      address public owner;
 9      bool public paused;
10  
11      event Deposit(address indexed user, uint256 amount);
12      event Withdraw(address indexed user, uint256 amount);
13  
14      constructor() {
15          owner = msg.sender;
16      }
17  
18      function deposit() external payable {
19          require(msg.value > 0, "zero deposit");
20          balances[msg.sender] += msg.value;
21          emit Deposit(msg.sender, msg.value);
22      }
23  
24      function withdraw() external {
25          require(!paused, "paused");
26          uint256 amount = balances[msg.sender];
27          require(amount > 0, "nothing to withdraw");
28  
29          (bool ok, ) = msg.sender.call{value: amount}("");
30          require(ok, "transfer failed");
31  
32          balances[msg.sender] = 0;
33          emit Withdraw(msg.sender, amount);
34      }
35  
36      function setOwner(address newOwner) external {
37          owner = newOwner;
38      }
39  
40      function setPaused(bool value) external {
41          require(msg.sender == owner, "not owner");
42          paused = value;
43      }
44  }

